// Generates src/theia/shader/textures/logoMg.ts — embedded base64 copy of logo-mg.png
// for worker-safe loading. `?inline`/`?url` emit `new URL(..., import.meta.url /
// self.location.href)` inside worker bundles — invalid under blob:file:/// in Electron
// prod. A data: URI fetches identically in worker and main thread.
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const png = fs.readFileSync(path.join(root, 'src/theia/shader/textures/logo-mg.png'));
const b64 = png.toString('base64');
const out = [
  '// AUTO-GENERATED by scripts/gen-logo-b64.cjs — do not edit by hand.',
  '// Embedded copy of logo-mg.png for worker-safe loading (WAVE 8417).',
  "// `?inline`/`?url` emit `new URL(..., import.meta.url/self.location.href)` inside",
  '// worker bundles — invalid under blob:file:/// in Electron prod. A data: URI',
  '// fetches identically in worker and main thread with zero asset-pipeline code.',
  `export const LOGO_MG_DATA_URI = 'data:image/png;base64,${b64}'`,
  '',
].join('\n');
fs.writeFileSync(path.join(root, 'src/theia/shader/textures/logoMg.ts'), out);
console.log('written logoMg.ts:', out.length, 'bytes');
